/**
 * Bader License — device fingerprint
 * ⚠️  لا تعدّل هذا الملف. تغييره يُبطل تراخيص كل الزبائن الحاليين.
 * ⚠️  DO NOT EDIT THIS FILE. Changing it invalidates every existing customer license.
 *
 * Builds a stable fingerprint of the Windows machine from hardware identifiers that do not
 * change when the user reinstalls the program or updates Windows:
 *   - the machine GUID (registry: HKLM\SOFTWARE\Microsoft\Cryptography\MachineGuid)
 *   - the motherboard / BIOS serial, the disk serial and the CPU id (via WMIC/PowerShell)
 *
 * Several sources are combined so that replacing one part (e.g. a disk) still lets the program
 * run, while copying the .exe to a completely different machine does not.
 *
 * Runs ONLY in the Electron main process (never the renderer), so the customer cannot see or
 * change it from the app window.
 */
'use strict';

const crypto = require('crypto');
const os = require('os');
const { execFileSync } = require('child_process');

const SALT = 'bader-license-device-v1';

function run(cmd, args) {
    try {
        return String(execFileSync(cmd, args, { timeout: 7000, windowsHide: true, stdio: ['ignore', 'pipe', 'ignore'] }) || '');
    } catch (e) {
        return '';
    }
}

/** Read a single registry value (Windows). */
function regValue(keyPath, name) {
    const out = run('reg', ['query', keyPath, '/v', name]);
    const m = out.match(new RegExp(name + '\\s+REG_[A-Z_]+\\s+(.+)', 'i'));
    return m ? m[1].trim() : '';
}

/** First non-empty, non-generic value of a WMIC column. */
function wmic(section, column) {
    const out = run('cmd', ['/c', 'wmic', section, 'get', column]);
    const lines = out.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
    lines.shift(); // header
    for (const line of lines) {
        const v = line.trim();
        if (v && !/^(to be filled|default string|none|n\/?a|system serial number|0+|null)$/i.test(v)) {
            return v;
        }
    }
    return '';
}

/** PowerShell fallback when WMIC is absent (Windows 11 24H2+). */
function psValue(expression) {
    const out = run('powershell', ['-NoProfile', '-NonInteractive', '-Command', expression]);
    const v = out.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).pop() || '';
    return /^(to be filled|default string|none|n\/?a|0+|null)$/i.test(v) ? '' : v;
}

function collectWindows() {
    const parts = [];
    parts.push(regValue('HKLM\\SOFTWARE\\Microsoft\\Cryptography', 'MachineGuid'));

    let board = wmic('baseboard', 'SerialNumber');
    if (!board) board = psValue('(Get-CimInstance Win32_BaseBoard).SerialNumber');
    parts.push(board);

    let bios = wmic('bios', 'SerialNumber');
    if (!bios) bios = psValue('(Get-CimInstance Win32_BIOS).SerialNumber');
    parts.push(bios);

    let cpu = wmic('cpu', 'ProcessorId');
    if (!cpu) cpu = psValue('(Get-CimInstance Win32_Processor).ProcessorId');
    parts.push(cpu);

    let disk = wmic('diskdrive', 'SerialNumber');
    if (!disk) disk = psValue('(Get-CimInstance Win32_DiskDrive | Select-Object -First 1).SerialNumber');
    parts.push(disk);

    let uuid = wmic('csproduct', 'UUID');
    if (!uuid) uuid = psValue('(Get-CimInstance Win32_ComputerSystemProduct).UUID');
    if (uuid && !/^(0{8}-0{4}|ffffffff-ffff)/i.test(uuid)) parts.push(uuid);

    return parts.filter(Boolean);
}

function collectUnix() {
    // Development / macOS / Linux: good enough so the program runs while you build it.
    const parts = [];
    if (process.platform === 'darwin') {
        const out = run('ioreg', ['-rd1', '-c', 'IOPlatformExpertDevice']);
        const m = out.match(/IOPlatformUUID"\s*=\s*"([^"]+)"/);
        if (m) parts.push(m[1]);
    } else {
        for (const f of ['/etc/machine-id', '/var/lib/dbus/machine-id']) {
            try {
                const v = require('fs').readFileSync(f, 'utf8').trim();
                if (v) { parts.push(v); break; }
            } catch (e) { /* ignore */ }
        }
    }
    return parts.filter(Boolean);
}

/**
 * Stable device fingerprint: 64 hex characters (SHA-256). Never changes on the same machine.
 * Falls back to the hostname + MAC only if no hardware id is available, so activation never crashes.
 */
function getDeviceId() {
    let parts = process.platform === 'win32' ? collectWindows() : collectUnix();

    if (parts.length === 0) {
        parts.push(os.hostname());
        const nets = os.networkInterfaces();
        for (const name of Object.keys(nets)) {
            for (const net of nets[name] || []) {
                if (!net.internal && net.mac && net.mac !== '00:00:00:00:00:00') {
                    parts.push(net.mac);
                    break;
                }
            }
        }
    }

    const basis = SALT + '|' + parts.map((p) => String(p).toLowerCase().replace(/\s+/g, '')).join('|');
    return crypto.createHash('sha256').update(basis).digest('hex');
}

/** Short, human-friendly device name shown in the dashboard (e.g. "DESKTOP-ABC — Windows 10"). */
function getDeviceLabel() {
    const host = os.hostname() || 'PC';
    const plat = process.platform === 'win32' ? 'Windows' : (process.platform === 'darwin' ? 'macOS' : 'Linux');
    const rel = (os.release() || '').split('.').slice(0, 2).join('.');
    return (host + ' — ' + plat + (rel ? ' ' + rel : '')).slice(0, 120);
}

module.exports = { getDeviceId, getDeviceLabel };
